const workcenterId = $.wcId || "wc-vmc-c1";
const tz = $.tz || $momentTzGuess();
const weeksForTrend = $.weeks || 12;

const now = $moment().tz(tz);
const nowUtc = now.format('YYYY-MM-DDTHH:mm:ss.SSSZ');

const currentHourStart = $moment(now).startOf('hour').format('YYYY-MM-DDTHH:mm:ss.SSSZ');
const currentHourEnd = $moment(now).startOf('hour').add(1, 'hour').format('YYYY-MM-DDTHH:mm:ss.SSSZ');

const window24hStart = $moment(now).subtract(24, 'hours').format('YYYY-MM-DDTHH:mm:ss.SSSZ');
const window30dStart = $moment(now).subtract(30, 'days').toISOString();
const window60dStart = $moment(now).subtract(60, 'days').toISOString();
const window90dStart = $moment(now).subtract(90, 'days').toISOString();

const dayStart = $moment(now).startOf('day').format('YYYY-MM-DDTHH:mm:ss.SSSZ');
const dayEnd = $moment(now).endOf('day').format('YYYY-MM-DDTHH:mm:ss.SSSZ');

// Weekly boundaries for trend chart (most recent week first)
const weeklyBoundaries = [];
for (let i = 0; i < weeksForTrend; i++) {
  const weekEnd = $moment(now).subtract(i, 'weeks').endOf('week');
  const weekStart = $moment(now).subtract(i, 'weeks').startOf('week');
  
  weeklyBoundaries.push({
    weekIndex: i,
    weekLabel: weekStart.format('MMM D'),
    start: weekStart.toISOString(),
    end: weekEnd.toISOString()
  });
}

// Reverse to chronological order (oldest first) for charting
const weeklyBoundariesChronological = [...weeklyBoundaries].reverse();

// Workcenter lookup
const wcQuery = await $query({
  statement: `query GetWorkcenter($wcId: String!) {
    workcenter(where: { id: { _eq: $wcId } }) {
      edges { node { id code name scheduleGroupId } }
    }
  }`,
  variables: { wcId: workcenterId }
});

const workcenter = wcQuery?.workcenter?.edges?.[0]?.node || null;
const scheduleGroupId = workcenter?.scheduleGroupId || null;

// Current shift from schedule group
let currentSchedule = null;
let shiftStart = null;
let shiftEnd = null;

if (scheduleGroupId) {
  const sg = await $scheduleGroup(scheduleGroupId);
  const currentSchedules = await sg.getCurrentSchedules(now, now, { inclusive: true });
  currentSchedule = currentSchedules?.[0] || null;
  
  if (currentSchedule?.range) {
    shiftStart = currentSchedule.range.start;
    shiftEnd = currentSchedule.range.end;
  }
}

return {
  workcenterId,
  timezone: tz,
  workcenter,
  currentSchedule: currentSchedule ? {
    scheduleId: currentSchedule.scheduleId,
    shiftStart: shiftStart,
    shiftEnd: shiftEnd,
    exception: currentSchedule.exception
  } : null,
  boundaries: {
    now: nowUtc,
    currentHourStart,
    currentHourEnd,
    window24hStart,
    window90dStart,
    window60dStart,
    window30dStart,
    dayStart,
    dayEnd,
    shiftStart,
    shiftEnd,
    weeklyBoundaries: weeklyBoundariesChronological
  }
};
